-- United States Government final module. Run seed_usgov_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'united-states-government';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Final Assessment: Civic Action Report and Presentation$j$, $j${"prompt": "Write a civic report of at least 500 words and prepare a short presentation of its main ideas. Choose one topic: (a) how a bill becomes a law, followed through one real or sample bill; (b) a landmark Supreme Court case and its effect on citizens; (c) a right in the Bill of Rights and how it protects people today; (d) how a local government in Broward County or Florida solves one community problem; or (e) a topic approved by your administrator. Write complete sentences and label each part. Proverbs 11:14 says, Where no counsel is, the people fall: but in the multitude of counsellors there is safety.\n\nPart 1: Question and Thesis. State a clear question and a thesis about your topic.\nPart 2: Sources. List at least three reliable sources, such as the Constitution, a government website, a court opinion or a news report, and tell how you judged each.\nPart 3: The Report. Explain your topic with an introduction, at least three body paragraphs and a conclusion. Connect it to at least two principles of the Constitution, and name the branch or level of government involved.\nPart 4: Scripture Connection. Connect your topic to a passage of Scripture in the King James Version and explain the link.\nPart 5: Citizen Action Plan. Describe one peaceful, lawful action you can take as a citizen about your topic, such as registering to vote, writing to an official, attending a meeting or volunteering.\nPart 6: Presentation Plan. Write a three part outline and an opening line for a three minute talk.", "rubric": "100 points. Part 1, question and thesis: 10 points. Part 2, sources: 10 points. Part 3, report content, accuracy and use of constitutional principles: 40 points. Part 4, Scripture connection: 8 points. Part 5, citizen action plan: 12 points. Part 6, presentation plan: 10 points. Grammar, conventions and respectful tone: 10 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: Civic Action Report and Presentation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Final Exam: United States Government$j$, $j${"questions": [{"q": "Government gets its just powers from:", "options": ["The consent of the governed", "A king", "The wealthy", "The army"]}, {"q": "The Articles of Confederation failed partly because Congress could not:", "options": ["Tax the people", "Elect a governor", "Meet", "Print a flag"]}, {"q": "The Great Compromise created:", "options": ["A House by population and a Senate with equal states", "A national bank", "Two Presidents", "A monarchy"]}, {"q": "Separation of powers divides government into:", "options": ["Two parties", "Four houses", "Three branches", "Five courts"]}, {"q": "The Bill of Rights was ratified in:", "options": ["1865", "1776", "1791", "1920"]}, {"q": "An amendment is ratified by:", "options": ["The Supreme Court", "A simple majority in Congress", "Three fourths of the states", "The President alone"]}, {"q": "The Senate has:", "options": ["100 members", "50 members", "538 members", "435 members"]}, {"q": "A President must be at least:", "options": ["35 years old", "30 years old", "25 years old", "40 years old"]}, {"q": "A candidate needs how many electoral votes to win?", "options": ["100", "218", "270", "435"]}, {"q": "Judicial review means courts can:", "options": ["Write laws", "Declare war", "Collect taxes", "Decide if a law violates the Constitution"]}, {"q": "Powers shared by nation and states are called:", "options": ["Delegated powers", "Concurrent powers", "Reserved powers", "Impeachment powers"]}, {"q": "The Nineteenth Amendment:", "options": ["Banned poll taxes", "Ended slavery", "Gave women the right to vote", "Set the voting age at 18"]}, {"q": "The Establishment Clause means government may not:", "options": ["Set up an official church", "Hold elections", "Tax anyone", "Protect religion"]}, {"q": "A good poll uses:", "options": ["Only volunteers", "No margin of error", "Leading questions", "A random, representative sample"]}, {"q": "Jesus said, Render therefore unto Caesar the things which are Caesar's, and unto God the things that are God's, in:", "options": ["Acts 5:29", "Matthew 22:21", "Romans 13:1", "Titus 3:1"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: United States Government$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,0,2,2,2,0,0,2,3,1,2,0,3,1}'::int[], array[$j$The Declaration of Independence states this principle.$j$,$j$The national government lacked the power to tax.$j$,$j$It balanced large and small states.$j$,$j$Legislative, executive and judicial branches.$j$,$j$The first ten amendments became law in 1791.$j$,$j$Article V requires three fourths of the states.$j$,$j$Each state has two Senators.$j$,$j$Article II sets the minimum age at 35.$j$,$j$A majority of 538 electors is 270.$j$,$j$Marbury v. Madison established it in 1803.$j$,$j$Taxing and building roads are examples.$j$,$j$It was ratified in 1920.$j$,$j$It prohibits an official national religion.$j$,$j$Fair sampling and wording make a reliable poll.$j$,$j$Jesus taught duty to both government and God.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: United States Government$j$ on conflict (item_id) do nothing;
end
$seed$;
